// 木鱼音效（三层合成：主体 + 泛音 + 敲击噪声）
const now = audioCtx.currentTime;

// 第一层：主体低音（基于原代码中的木鱼音色）
const osc1 = audioCtx.createOscillator();
const gain1 = audioCtx.createGain();
osc1.connect(gain1);
gain1.connect(audioCtx.destination);
osc1.type = 'sine';                    // 原代码使用 sine 波
osc1.frequency.setValueAtTime(600, now);
osc1.frequency.exponentialRampToValueAtTime(600, now + 0.15);  // 原代码频率恒定
gain1.gain.setValueAtTime(0.3, now);
gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
osc1.start(now);
osc1.stop(now + 0.15);

// 第二层：轻微泛音（为原木鱼音色增加一点层次感）
const osc2 = audioCtx.createOscillator();
const gain2 = audioCtx.createGain();
osc2.connect(gain2);
gain2.connect(audioCtx.destination);
osc2.type = 'sine';
osc2.frequency.setValueAtTime(1200, now);     // 两倍频的泛音
osc2.frequency.exponentialRampToValueAtTime(1200, now + 0.1);
gain2.gain.setValueAtTime(0.1, now);          // 音量较小，作为背景
gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
osc2.start(now);
osc2.stop(now + 0.1);

// 第三层：轻微敲击噪声（增强敲击感）
const bufLen = Math.floor(audioCtx.sampleRate * 0.01);  // 更短的噪声
const buf = audioCtx.createBuffer(1, bufLen, audioCtx.sampleRate);
const data = buf.getChannelData(0);
for (let i = 0; i < bufLen; i++) {
    data[i] = (Math.random() * 2 - 1) * (1 - i / bufLen) * 0.15;  // 较低音量
}
const src = audioCtx.createBufferSource();
const gain3 = audioCtx.createGain();
src.buffer = buf;
src.connect(gain3);
gain3.connect(audioCtx.destination);
gain3.gain.setValueAtTime(0.2, now);
gain3.gain.exponentialRampToValueAtTime(0.001, now + 0.02);
src.start(now);
